.texture-0 { background: #474747; }
.texture-1 { background: repeating-linear-gradient(45deg,#303030 0 4px,#5b5b5b 4px 5px); }
.texture-2 { background: radial-gradient(#7d7d7d 1px,transparent 1.5px) 0 0 / 7px 7px,#323232; }
