.sl-check--chip .sl-check__box::before { display: none; }
.sl-check--chip .sl-check__box svg { width: 18px; height: 18px; stroke: var(--check-paper); }
.sl-check--chip:has(:checked) { background: #404040; border-color: #b6b6b6; }
