.check-tree .sl-check::before { content: ""; position: absolute; left: -10px; width: 12px; height: 1px; background: #5e5e5e; }
.check-nested > .sl-check { min-height: 65px; }
@media (max-width:420px) {
  .swatch-face { width: 49px; height: 49px; }
