import{retainFont as b}from"./react-font.mjs";const x="nested-checkbox";const m='<fieldset class="sl-check-card check-list check-nested" data-demo="nested"><legend class="visually-hidden">Project assets</legend><label class="sl-check sl-check--outline"><input class="sl-check__input" type="checkbox" id="nested-all" name="nested-all" data-parent><span class="sl-check__box" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path class="sl-check__tick" pathLength="1" d="m5 12 4.5 4.5L19 7"/><path class="sl-check__dash" d="M6 12h12"/></svg></span><span class="sl-check__copy"><span class="sl-check__title">Project assets</span><span class="sl-check__hint">Select all</span></span></label><div class="check-tree"><label class="sl-check sl-check--outline"><input class="sl-check__input" type="checkbox" id="nested-0" name="nested-0" data-child checked><span class="sl-check__box" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path class="sl-check__tick" pathLength="1" d="m5 12 4.5 4.5L19 7"/><path class="sl-check__dash" d="M6 12h12"/></svg></span><span class="sl-check__copy"><span class="sl-check__title">Icons</span></span></label><label class="sl-check sl-check--outline"><input class="sl-check__input" type="checkbox" id="nested-1" name="nested-1" data-child><span class="sl-check__box" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path class="sl-check__tick" pathLength="1" d="m5 12 4.5 4.5L19 7"/><path class="sl-check__dash" d="M6 12h12"/></svg></span><span class="sl-check__copy"><span class="sl-check__title">Illustrations</span></span></label><label class="sl-check sl-check--outline"><input class="sl-check__input" type="checkbox" id="nested-2" name="nested-2" data-child><span class="sl-check__box" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path class="sl-check__tick" pathLength="1" d="m5 12 4.5 4.5L19 7"/><path class="sl-check__dash" d="M6 12h12"/></svg></span><span class="sl-check__copy"><span class="sl-check__title">Fonts</span></span><