import{retainFont as R}from"./react-font.mjs";const M="export-menu";const U='<div class="menu-demo menu-study" data-menu="export" data-motion="joined" data-confirm="true"><div class="study-joined"><button type="button" class="menu-trigger" data-trigger aria-expanded="false" aria-haspopup="menu" aria-controls="study-export"><i class="menu-glyph " data-icon="file" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><path d="M7 4h10l6 6v12a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm10 0v6h6"/></svg></i><span class="menu-trigger-label" data-trigger-label>Export file</span><i class="menu-glyph menu-chevron" data-icon="chevron" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><path d="m8 11 6 6 6-6"/></svg></i></button><div class="study-reveal"><div class="menu-panel" id="study-export" role="menu" aria-label="Export menu" aria-hidden="true" inert><div class="menu-overline">CHOOSE A FORMAT</div><div class="format-grid"><button type="button" class="format-option" role="menuitemradio" data-value="pdf" data-label="PDF" aria-checked="true" tabindex="-1"><i class="menu-glyph " data-icon="file" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><path d="M7 4h10l6 6v12a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm10 0v6h6"/></svg></i><strong>PDF</strong><small>Document</small><i class="menu-glyph menu-check" data-icon="check" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><path d="m5 14 6 6L23 8"/></svg></i></button><button type="button" class="format-option" role="menuitemradio" data-value="png" data-label="PNG" aria-checked="false" tabindex="-1"><i class="menu-glyph " data-icon="file" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><path d="M7 4