const icons={"file":"<i class=\"menu-glyph \" data-icon=\"file\" aria-hidden=\"true\"><svg viewBox=\"0 0 28 28\" xmlns=\"http://www.w3.org/2000/svg\" focusable=\"false\" aria-hidden=\"true\"><path d=\"M7 4h10l6 6v12a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm10 0v6h6\"/></svg></i>","folder":"<i class=\"menu-glyph \" data-icon=\"folder\" aria-hidden=\"true\"><svg viewBox=\"0 0 28 28\" xmlns=\"http://www.w3.org/2000/svg\" focusable=\"false\" aria-hidden=\"true\"><path d=\"M4.5 9a2 2 0 0 1 2-2h5l2.5 3h7.5a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-15a2 2 0 0 1-2-2Z\"/></svg></i>","chevron":"<i class=\"menu-glyph \" data-icon=\"chevron\" aria-hidden=\"true\"><svg viewBox=\"0 0 28 28\" xmlns=\"http://www.w3.org/2000/svg\" focusable=\"false\" aria-hidden=\"true\"><path d=\"m8 11 6 6 6-6\"/></svg></i>","pin":"<i class=\"menu-glyph \" data-icon=\"pin\" aria-hidden=\"true\"><svg viewBox=\"0 0 28 28\" xmlns=\"http://www.w3.org/2000/svg\" focusable=\"false\" aria-hidden=\"true\"><path d=\"M17 4l7 7-2 2-2-2-5 5v4l-7-7h4l5-5-2-2ZM11.5 16.5 5 23\"/></svg></i>"};
