 const kind=root.dataset.navigation;
 if(['tabs','views'].includes(kind)){
  const track=root.querySelector('.nav-track'),buttons=[...track.querySelectorAll('[role=tab]')],panels=[...root.querySelectorAll('[role=tabpanel]')];let selected=0;
