  handle.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0||!opened)return;drag={id:e.pointerId,y:e.clientY,dy:0};root.dataset.dragging='true';handle.setPointerCapture(e.pointerId);},{signal});
