import{retainFont as J}from"./react-font.mjs";const V="drawer-overlay";const Q='<div class="overlay-demo" data-overlay="drawer" data-open="false"><div class="overlay-launch"><button class="overlay-trigger" type="button" data-trigger aria-haspopup="dialog" aria-expanded="false"><i class="menu-glyph " data-icon="file" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><path d="M7 4h10l6 6v12a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm10 0v6h6"/></svg></i><span>Project details</span></button><p class="overlay-feedback" data-feedback role="status">Try it here. Nothing leaves this preview.</p></div><dialog class="overlay-panel" aria-labelledby="panel-title"><button class="overlay-close" type="button" data-close aria-label="Close"><svg viewBox="0 0 28 28" aria-hidden="true"><path d="m8 8 12 12M20 8 8 20"/></svg></button><div class="overlay-eyebrow">WORKSPACE</div><h2 id="panel-title">Project details</h2><p>Keep the important things together.</p><form data-form><label class="overlay-field">Project name<input name="project" value="Studio project" required maxlength="48" autocomplete="off"></label><fieldset class="status-choices"><legend>Project status</legend><label><input type="radio" name="status" value="Planned" ><span>Planned</span></label><label><input type="radio" name="status" value="Active" checked><span>Active</span></label><label><input type="radio" name="status" value="Done" ><span>Done</span></label></fieldset><div class="drawer-note"><i class="menu-glyph " data-icon="clock" aria-hidden="true"><svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg" focusable="false" aria-hidden="true"><circle cx="14" cy="14" r="9"/><path d="M14 8v6l4 3"/></svg></i><span>Changes stay in this preview.</span></div><div class="overlay-actions"><button type="button" data-close>Cancel</button><button class="overlay-primary" type="submit">Save changes</button></div></form></dialog></div>';const $="@font-face{font-