[data-overlay=tour] .overlay-panel{padding:17px 18px}.tour-preview{padding:22px 12px 12px;border:1px solid #b6b6b617;border-radius:11px;background:#1d1d1d;margin:10px 14px 20px 0;display:grid;gap:6px}.tour-preview>div{display:flex;align-items:center;gap:9px;font-size:11px;padding:8px;border:1px solid transparent;border-radius:6px;color:#868686;transition:border-color 230ms ease,color 230ms ease,background-color 230ms ease}.tour-preview [data-highlight=true]{border-color:#d9d9d988;background:#b5b5b512;color:#e2e2e2}.tour-preview .menu-glyph{width:20px;height:20px}.tour-copy{min-height:110px}.tour-copy .overlay-eyebrow{display:block;margin:0 0 10px;font-size:9px}.tour-copy h2{font-size:20px;margin:0 0 10px}[data-overlay=tour] .overlay-actions{margin-top:10px;justify-content:space-between}
.overlay-demo:not([data-overlay=document]){grid-template-columns:minmax(0,1fr)}
[data-overlay=quickedit] .overlay-feedback{overflow-wrap:anywhere}
.trigger-icon-stack{position:relative;display:block;flex:0 0 25px;width:25px;height:25px;font-style:normal}
.trigger-icon-stack>.menu-glyph,.trigger-result-check{position:absolute;inset:0;width:25px;height:25px;transition:opacity 180ms ease,transform 260ms var(--overlay-ease)}
.trigger-result-check{opacity:0;transform:scale(.85);stroke-width:1.8;pointer-events:none}.trigger-result-check path{stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 300ms var(--overlay-ease)}
.trigger-result-label{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:25px}
.overlay-trigger[data-result=true]{background:#363636;border-color:#b3b3b373;color:#e8e8e8}
.overlay-trigger[data-result=true]:hover{background:#404040;border-color:#c8c8c8}
.overlay-trigger[data-result=true] .menu-glyph{opacity:0;transform:scale(.85)}
.overlay-trigger[data-result=true] .trigger-result-check{opacity:1;transform:none}
.overlay-trigger[data-result=true] .trigger-result-check path{stroke-dashoffset:0}
[hidden]{display:none!important}@media(max-width:290px){.preview-paper{padding:19px 14px}.preview-paper h3{font-size:21px}.tour-preview{margin-bottom:15px}.tour-copy{min-height:130px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after,*::backdrop{transition:none!important;animation:none!important}}
@media(max-height:450px){
 [data-overlay=palette] .overlay-panel{top:12px;max-height:calc(100svh - 24px);display:flex;flex-direction:column;overflow:hidden}
 [data-overlay=palette] .overlay-panel:not([open]){display:none}
 .command-search,.command-footnote{flex-shrink:0}
 .command-results{min-height:0;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#787878 transparent}
 .tour-preview{padding:10px;margin:8px 14px 14px 0;gap:3px}
 .tour-preview>div{padding:5px 8px}
 .tour-copy{min-height:0}
 [data-overlay=tour] .overlay-panel{padding:16px}
 [data-overlay=tour] .overlay-actions{margin-top:14px}
 [data-overlay=quickedit] .overlay-panel{padding:16px;max-height:calc(100svh - 24px);overflow-y:auto}
 .confirm-summary{margin-top:14px;padding:10px}
}
@media(max-height:350px){
 [data-overlay=confirm] .overlay-emblem{display:none}
 [data-overlay=confirm] .overlay-panel h2{padding-right:24px;margin-top:0}
 .tour-preview{display:flex;padding:6px;margin-bottom:12px;gap:4px}
 .tour-preview>div{flex:1;justify-content:center;padding:6px 0}
 .tour-preview>div>span{display:none}
 .tour-copy .overlay-eyebrow{margin-bottom:7px}
 .tour-copy h2{font-size:19px;margin-bottom:8px}
}
