.fb-demo{--motion-duration-short-2:100ms;--motion-duration-short-4:200ms;--motion-duration-medium-1:250ms;--motion-duration-medium-2:300ms;--motion-duration-medium-3:350ms;--motion-duration-medium-4:400ms;--motion-easing-standard:cubic-bezier(0.2,0,0,1);--motion-easing-emphasized-decelerate:cubic-bezier(0.05,0.7,0.1,1);--motion-easing-ease-in-out-gentle:cubic-bezier(0.4,0,0.2,1); --fb-ink:#222222;--fb-hover:#2e2e2e;--fb-surface:#292929;--fb-edge:#464646;--fb-text:#f6f6f6;--fb-muted:#bdbdbd;--fb-accent:#e0e0e0;--fb-danger:#efb8a6;--fb-warning:#e8d4a5;--fb-focus:#737373;--fb-outside:#5e5e5e;width:320px;max-width:100%;font:14px/1.45 'Instrument Sans',sans-serif;color:var(--fb-text);font-synthesis:none;-webkit-font-smoothing:antialiased;position:relative;isolation:isolate;outline:none}
.fb-demo,.fb-demo *,.fb-demo *::before,.fb-demo *::after{box-sizing:border-box}
