.fb-demo svg{width:22px;height:22px;display:block;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:none}.fb-card h3,.fb-card p{margin:0}.fb-card h3{font-size:15px;font-weight:550;letter-spacing:-.02em}.fb-card p{font-size:12px;color:var(--fb-muted);line-height:1.6;margin-top:5px;overflow-wrap:anywhere}.fb-overline{font-size:10px;letter-spacing:.075em;color:var(--fb-muted);text-transform:uppercase}.fb-card-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.fb-icon{display:grid;place-items:center;flex:none;width:34px;height:34px;border-radius:11px;background:#ffffff07;border:1px solid #ffffff13;color:var(--fb-accent)}
.fb-message{display:flex;align-items:center;gap:12px;padding:17px 14px 17px 16px}.fb-copy{min-width:0;flex:1}.fb-copy h3{font-size:14px}.fb-copy p{font-size:11px;margin-top:3px}.fb-close{width:28px;height:28px;display:grid;place-items:center;flex:none;padding:5px;border:0;border-radius:8px;background:transparent;color:var(--fb-muted);transition:background var(--motion-duration-short-4) ease,color var(--motion-duration-short-4) ease}.fb-close svg{width:16px;height:16px}.fb-close:hover{background:#ffffff0d;color:var(--fb-text)}
.fb-reveal{opacity:1;visibility:visible;transform:translateY(0);transition:opacity var(--motion-duration-medium-1) ease,transform var(--motion-duration-medium-2) var(--motion-easing-emphasized-decelerate),visibility 0s}
.fb-reveal[data-visible="false"]{opacity:0;visibility:hidden;transform:translateY(8px);pointer-events:none;transition:opacity var(--motion-duration-short-4) ease,transform var(--motion-duration-medium-1) var(--motion-easing-ease-in-out-gentle),visibility 0s var(--motion-duration-medium-1)}
.fb-demo[data-tone="error"] .fb-icon{color:var(--fb-danger)}.fb-demo[data-tone="info"] .fb-icon{color:#bacdd9}
.fb-tools{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:8px;min-height:40px;margin-top:14px}.fb-button{border:0;border-radius:11px;padding:10px 16px;min-height:38px;background:var(--fb-ink);color:var(--fb-text);font-size:12px!important;font-weight:550!important;box-shadow:inset 0 1px #ffffff12,0 1px 2px #0000000d;transition:transform var(--motion-duration-medium-2) var(--motion-easing-emphasized-decelerate),background-color var(--motion-duration-short-4) ease;white-space:nowrap}
