.fb-stack{width:100%;display:flex;flex-direction:column;gap:0;max-height:238px}.fb-stack-item{display:grid;grid-template-rows:1fr;opacity:1;transform:translateY(0);transition:grid-template-rows var(--motion-duration-medium-2) var(--motion-easing-standard),opacity var(--motion-duration-medium-1) ease,transform var(--motion-duration-medium-2) var(--motion-easing-emphasized-decelerate)}.fb-stack-item[data-visible="false"]{grid-template-rows:0fr;opacity:0;transform:translateY(8px);pointer-events:none}.fb-stack-clip{overflow:hidden;min-height:0}.fb-stack .fb-card{margin-bottom:7px;padding:12px;border-radius:13px;box-shadow:inset 0 1px #ffffff0c,0 2px 3px #00000008}.fb-stack .fb-icon{width:29px;height:29px;border-radius:9px}.fb-stack .fb-icon svg{width:18px;height:18px}.fb-stack h3{font-size:12px}.fb-stack p{font-size:10px}.fb-stack .fb-close{width:24px;height:24px}.fb-queue{font-size:11px;color:var(--fb-outside);text-align:center;height:16px;margin:0}
.fb-undo .fb-message{flex-wrap:wrap;gap:10px}.fb-undo .fb-copy{min-width:140px}.fb-row{display:flex;align-items:center;justify-content:space-between;gap:10px}.fb-meta-row{display:flex;justify-content:space-between;margin-top:13px;font-size:11px;color:var(--fb-muted)}.fb-divider{height:1px;background:#ffffff10;margin:17px 0}
