uild time. */
@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}
.dd-demo{--motion-duration-short-2:100ms;--motion-duration-short-4:200ms;--motion-duration-medium-1:250ms;--motion-duration-medium-2:300ms;--motion-duration-medium-3:350ms;--motion-duration-medium-4:400ms;--motion-easing-standard:cubic-bezier(0.2,0,0,1);--motion-easing-emphasized-decelerate:cubic-bezier(0.05,0.7,0.1,1);--motion-easing-ease-in-out-gentle:cubic-bezier(0.4,0,0.2,1); --dd-ink:#222222;--dd-hover:#2f2f2f;--dd-edge:#464646;--dd-text:#f6f6f6;--dd-muted:#bdbdbd;--dd-accent:#e0e0e0;--dd-blue:#aec6d2;--dd-sand:#d3c4a8;--dd-warning:#e8d4a5;--dd-focus:#e0e0e0;--dd-outside:#5e5e5e;width:320px;max-width:100%;font:14px/1.45 'Instrument Sans',sans-serif;color:var(--dd-text);font-synthesis:none;-webkit-font-smoothing:antialiased;position:relative;isolation:isolate;outline:none}
