import{retainFont as xe}from"./react-font.mjs";const te="details-display";const be='<div class="dd-demo" data-display="details" tabindex="-1"><div class="dd-scene"><section class="dd-card dd-card--details" aria-label="Details list"><div class="dd-head"><h3>Project details</h3><span class="dd-icon"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m12 3 9 5-9 5-9-5Zm-9 9 9 5 9-5m-18 5 9 5 9-5"/></svg></span></div><dl class="dd-details"><div><dt>Project</dt><dd>Studio</dd></div><div><dt>Owner</dt><dd>Alex Lee</dd></div><div><dt>Visibility</dt><dd><span class="dd-pill">Private</span></dd></div></dl><div class="dd-collapse" data-expanded="false" data-extra aria-hidden="true" inert><div><dl class="dd-details dd-details--extra"><div><dt>Project ID</dt><dd class="dd-mono">PRJ-2048</dd></div><div><dt>Region</dt><dd>Europe</dd></div><div><dt>Created</dt><dd>Sep 01, 2026</dd></div></dl></div></div><div class="dd-bottom"><button class="dd-button" type="button" data-action="toggle" aria-expanded="false" >More details<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 9 6 6 6-6"/></svg></button></div></section></div><p class="dd-caption">Expand the properties without leaving the card.</p><span class="dd-sr" data-live role="status" aria-live="polite" aria-atomic="true"></span></div>';const he=`/* SL UI matte palette. M3 motion tokens are inserted at build time. */
@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}
.dd-demo{--motion-duration-short-2:100ms;--motion-duration-short-4:200ms;--motion-duration-medium-1:250ms;--motion-duration-medium-2:300ms;--motion-duration-medium-3:350ms;--motion-duration-medium-4:400ms;--motion-easing-standard:cubic-bezier(0.2,0,0,1);--motion-easing-emphasized-decelerate:cubic-bezier(0.05,0.7,0.1,1);--motion-easing-ease-in-out-gentle:cubic-bezier(0.4,0,0.2,1); --dd-ink:#222222;--dd-hover:#2f2f2f;--dd-edge:#464646;--dd-text:#f6f6f6;--dd-muted:#bdbdbd;--dd-accent:#e0e0e0;--dd-blue:#aec6d2;--dd-sand:#d3c4a8;--dd-warning:#e8d4a5;--dd-focus:#e0e0e0;--dd-outside:#5e5e5e;width:320px;max-width:100%;font:14px/1.45 'Instrument Sans',sans-serif;color:var(--dd-text);font-synthesis:none;-webkit-font-smoothing:antialiased;position:relative;isolation:isolate;outline:none}
.dd-demo,.dd-demo *,.dd-demo *::before,.dd-demo *::after{box-sizing:border-box}.dd-demo button{font:inherit;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent;user-select:none}.dd-demo button:focus-visible{outline:2px solid var(--dd-focus);outline-offset:3px}.dd-demo button:disabled{cursor:default;opacity:.5}.dd-demo [hidden]{display:none!important}.dd-demo svg{display:block;width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:none}
.dd-scene{height:390px;display:flex;align-items:center;justify-content:center}.dd-card{width:100%;padding:22px;background:var(--dd-ink);border:1px solid #ffffff0d;border-radius:17px;box-shadow:inset 0 1px #ffffff0c,0 3px 7px #00000010;color:var(--dd-text)}.dd-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:18px}.dd-card h3,.dd-card h4,.dd-card p{margin:0}.dd-card h3{font-size:14px;font-weight:550;letter-spacing:-.02em}.dd-card h4{font-size:15px;font-weight:550;overflow-wrap:anywhere}.dd-muted{color:var(--dd-muted);font-size:11px;line-height:1.6}.dd-icon{display:grid;place-items:center;flex:none;width:30px;height:30px;border:1px solid #ffffff13;border-radius:9px;background:#ffffff05;color:var(--dd-accent)}.dd-icon svg{width:18px;height:18px}.dd-overline{font-size:10px;color:var(--dd-muted);letter-spacing:.025em}.dd-pill{display:inline-flex;align-items:center;border:1px solid #e0e0e01c;border-radius:6px;padding:3px 7px;color:var(--dd-accent);background:#e0e0e008;font-size:10px;white-space:nowrap}.dd-caption{min-height:34px;margin:8px 4px 0;text-align:center;color:var(--dd-outside);font-size:11px;line-height:1.5}.dd-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.dd-segments{display:flex;width:max-content;max-width:100%;padding:3px;gap:2px;background:#191919;border:1px solid #ffffff0d;border-radius:9px}.dd-segments button{border:0;background:transparent;color:var(--dd-muted);padding:5px 10px;font-size:10px;line-height:1.4;border-radius:6px;transition:background var(--motion-duration-short-4) ease,color var(--motion-duration-short-4) ease}.dd-segments button[aria-pressed="true"]{background:#414141;color:var(--dd-text)}.dd-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:33px;padding:8px 11px;background:#323232;border:1px solid #ffffff13;border-radius:9px;color:var(--dd-accent);font-size:11px!important;line-height:1.4;transition:background var(--motion-duration-short-4) ease,transform var(--motion-duration-medium-2) var(--motion-easing-standard)}.dd-button:hover{background:var(--dd-hover)}.dd-button:active{transform:translateY(1px) scale(.98)}.dd-button svg{width:14px;height:14px;transition:transform var(--motion-duration-medium-3) var(--motion-easing-standard)}.dd-button[aria-expanded="true"] svg{transform:rotate(180deg)}.dd-bottom{display:flex;justify-content:center;margin-top:16px}.dd-collapse{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows var(--motion-duration-medium-3) var(--motion-easing-ease-in-out-gentle),opacity var(--motion-duration-medium-2) ease}.dd-collapse[data-expanded="true"]{grid-template-rows:1fr;opacity:1}.dd-collapse>div{min-height:0;overflow:hidden}
.dd-metric{display:flex;align-items:baseline;gap:13px;margin-top:22px;font-variant-numeric:tabular-nums}.dd-metric>[data-value]{font-size:39px;line-height:1.2;letter-spacing:-.065em;font-weight:550}.dd-trend{font-size:11px;color:var(--dd-accent)}.dd-metric+.dd-muted{margin-top:7px;font-size:10px}.dd-demo .dd-spark{width:100%;height:64px;margin:20px 0 8px;overflow:visible;stroke:var(--dd-accent);stroke-width:2}.dd-spark polyline{vector-effect:non-scaling-stroke}.dd-spark .dd-spark-guide{stroke:#ffffff10;stroke-width:1}.dd-foot{display:flex;justify-content:space-between;font-size:9px;color:var(--dd-muted)}
