.dd-avatars{display:flex;align-items:center;margin:24px 0 17px;padding-left:2px}.dd-avatar{width:43px;height:43px;flex:none;border:3px solid var(--dd-ink);border-radius:50%;margin-left:-2px;display:grid;place-items:center;font-size:12px!important;color:#272727;transition:transform var(--motion-duration-medium-2) var(--motion-easing-standard),box-shadow var(--motion-duration-short-4) ease;position:relative}.dd-avatar+.dd-avatar{margin-left:-8px}.dd-avatar:hover{z-index:2;transform:translateY(-3px)}.dd-avatar[aria-pressed="true"]{z-index:1;box-shadow:0 0 0 1px var(--dd-accent)}.dd-avatar--sage{background:#bed2c4}.dd-avatar--blue{background:#b4c7d2}.dd-avatar--sand{background:#d8cdb7}.dd-avatar--rose{background:#d7bfbb}.dd-avatar--more{background:#3a3a3a;color:var(--dd-text)}.dd-person{display:flex;justify-content:space-between;align-items:center;gap:10px}.dd-person strong{font-size:13px;font-weight:500}.dd-person>span{font-size:11px;color:var(--dd-muted)}.dd-member-list{display:grid;gap:2px;margin-top:16px;border-top:1px solid var(--dd-edge);padding-top:8px}.dd-member-list button{display:flex;align-items:center;gap:9px;border:0;background:none;color:var(--dd-text);padding:5px 0;text-align:left;font-size:11px;min-width:0}.dd-member-list button>svg{margin-left:auto;width:12px;height:12px;color:var(--dd-muted)}.dd-member-list button small{display:block;color:var(--dd-muted);font-size:9px}.dd-mini-avatar{width:24px;height:24px;display:grid;place-items:center;border-radius:50%;color:#2d2d2d;font-size:9px;flex:none}
