  .sl-component button:focus-visible { outline-color: Highlight; }
}
.sl-component .ab-hold { overflow: hidden; isolation: isolate; border-color: var(--action-accent); touch-action: none; }
.sl-component .ab-hold-fill { position: absolute; inset: 0; background: var(--action-accent); opacity: .16; z-index: -1; transform: scaleX(0); transform-origin: left; transition: transform 160ms ease; }
.sl-component[data-holding="true"] .ab-hold-fill { transition: none; }
.sl-component .ab-hold-stroke { stroke: var(--action-accent); stroke-width: 2.6; stroke-dasharray: 100; stroke-dashoffset: 100; }
.sl-component[data-holding="true"] .ab-hold { border-color: var(--action-focus); }
.sl-component [data-cancel] { margin-top: 12px; }

