.sl-component .sl-picker-body { scrollbar-width: none; }
.sl-component .sl-time-list button { display: block; width: 100%; min-height: 32px; padding: 4px; margin-bottom: 3px; border-color: transparent; font-variant-numeric: tabular-nums; }
.sl-component .sl-time-draft { font-size: 18px; color: var(--field-accent); font-variant-numeric: tabular-nums; }
.sl-component .sl-picker-footer button { padding: 7px 9px; font-size: 12px; }
