.sl-component .sl-note { margin: 12px 0 0; color: var(--field-muted); font-size: 12px; overflow-wrap: anywhere; }
.sl-component .sl-status { min-height: 36px; margin: 14px 0 0; font-size: 12px; color: var(--field-muted); overflow-wrap: anywhere; }
.sl-component[data-invalid="true"] .sl-status { color: var(--field-error); }
.sl-component output { display: block; margin-top: 16px; padding-top: 12px; border-top: 1px solid var(--field-border); color: var(--field-accent); font-size: 14px; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
@media (prefers-reduced-motion: reduce) { .sl-component *, .sl-component *::before, .sl-component *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; } }
@media (forced-colors: active) { .sl-component { border-color: CanvasText; } .sl-component button, .sl-component input, .sl-component select { border: 1px solid ButtonText; } .sl-component :focus-visible { outline: 2px solid Highlight; outline-offset: -2px; } }
.sl-component .sl-row > .sl-picker-label { flex: 0 0 52px; }
.sl-component .sl-picker-label > span { display: block; color: var(--field-muted); font-size: 12px; margin-bottom: 6px; }
.sl-component .sl-picker { display: block; width: 52px; height: 44px; padding: 6px; background: var(--field-hover); border: 1px solid var(--field-border); border-radius: 8px; cursor: pointer; }
.sl-component .sl-picker > span { display: block; width: 100%; height: 100%; background: var(--chosen-color, #b6cbbb); border: 1px solid #ffffff66; border-radius: 4px; }
.sl-component [data-color] { display: flex; align-items: center; gap: 6px; padding: 7px 9px; font-size: 12px; }
.sl-component [data-color][aria-pressed="true"] { border-color: var(--field-accent); background: var(--field-active); }
.sl-component .sl-dot { width: 10px; height: 10px; border-radius: 50%; border: 1px solid currentColor; }
.sl-component .sl-sage { background: #b6cbbb; } .sl-component .sl-sand { background: #c7bba8; } .sl-component .sl-mist { background: #abbecd; }
.sl-component .sl-color-plane { position: relative; height: 88px; margin: 5px; border-radius: 7px; background: linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent), hsl(var(--hue, 140) 100% 50%); touch-action: none; cursor: crosshair; }
.sl-component .sl-color-thumb { position: absolute; width: 12px; height: 12px; border: 2px solid #fff; box-shadow: 0 0 0 1px #0008; border-radius: 50%; transform: translate(-50%, -50%); pointer-events: none; }
.sl-component .sl-color-sliders { display: grid; gap: 8px; margin-top: 10px; }
.sl-component .sl-color-sliders label { display: grid; gap: 3px; }
.sl-component .sl-color-sliders label > span { margin: 0; font-size: 11px; }
.sl-component .sl-color-sliders input[type="range"] { appearance: none; width: 100%; height: 18px; min-height: 18px; padding: 0; margin: 0; border: 0; border-radius: 8px; background: transparent; cursor: pointer; }
.sl-component .sl-color-sliders input::-webkit-slider-runnable-track { height: 6px; border-radius: 4px; background: var(--field-border); }
.sl-component .sl-color-sliders input::-moz-range-track { height: 6px; border-radius: 4px; background: var(--field-border); }
.sl-component .sl-color-sliders input[data-channel="0"]::-webkit-slider-runnable-track { background: linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00); }
.sl-component .sl-color-sliders input[data-channel="0"]::-moz-range-track { background: linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00); }
.sl-component .sl-color-sliders input::-webkit-slider-thumb { appearance: none; margin-top: -4px; width: 14px; height: 14px; border-radius: 50%; background: var(--field-accent); border: 2px solid var(--field-surface); box-shadow: 0 0 0 1px var(--field-border); }
.sl-component .sl-color-sliders input::-moz-range-thumb { width: 10px; height: 10px; border-radius: 50%; background: var(--field-accent); border: 2px solid var(--field-surface); box-shadow: 0 0 0 1px var(--field-border); }
.sl-component .sl-color-sliders input:focus-visible { outline: 2px solid var(--field-focus); outline-offset: 2px; }
.sl-component .sl-color-sample { font-size: 11px; font-variant-numeric: tabular-nums; padding-left: 16px; position: relative; }
.sl-component .sl-color-sample::before { content: ''; position: absolute; left: 0; top: 3px; width: 10px; height: 10px; background: var(--chosen-color); border: 1px solid var(--field-muted); border-radius: 3px; }
.sl-component .sl-picker-footer button { font-size: 12px; padding: 6px 8px; }
