      radios('grid', state.grid);
      radios('guides', state.guides);
      root.dataset.grid = state.grid;
      root.dataset.guides = state.guides;
      text('[data-status]', 'Grid: ' + state.grid + ' / Guides: ' + state.guides);
    }
    function action(name, button) {
      // All controls use direct selections.
    }
