      return { primary: enumValue(next.primary, ['headphones', 'speakers']), fallback: booleanValue(next.fallback) };
    }
    function render() {
      const first = state.primary === 'headphones' ? 'Headphones' : 'Speakers';
      const second = state.primary === 'headphones' ? 'Speakers' : 'Headphones';
      root.dataset.fallback = String(state.fallback);
      text('[data-primary]', first);
      text('[data-secondary]', second);
      text('[data-secondary-label]', state.fallback ? 'Fallback' : 'Fallback disabled');
      toggle('fallback', state.fallback);
      q('[data-action="swap"]').disabled = !state.fallback;
      text('[data-status]', state.fallback ? first + ' first, ' + second.toLowerCase() + ' second' : first + ' only');
    }
    function action(name, button) {
      if (name === 'swap' && state.fallback) setState({ primary: state.primary === 'headphones' ? 'speakers' : 'headphones' }, { emit: true });
    }
    function setState(patch, { emit = false } = {}) {
      if (destroyed) return;
