  .sl-component { --choice-bg: Canvas; --choice-surface: Canvas; --choice-text: CanvasText; --choice-muted: CanvasText; --choice-border: ButtonBorder; --choice-control: ButtonText; --choice-accent: Highlight; --choice-accent-ink: HighlightText; --choice-focus: Highlight; --choice-selected: Canvas; }
