.sl-component {
  --choice-bg: #222222; --choice-surface: #2c2c2c; --choice-text: #f8f8f8;
  --choice-muted: #c1c1c1; --choice-border: #5a5a5a; --choice-control: #999999;
  --choice-accent: #e0e0e0; --choice-accent-ink: #262626; --choice-focus: #e0e0e0;
  --choice-selected: #3c3c3c; --choice-ease: cubic-bezier(.22,.61,.36,1);
  box-sizing: border-box; width: min(320px,100%); min-width: 0; margin: 0; padding: 16px;
  border: 1px solid var(--choice-border); border-radius: 14px; background: var(--choice-bg);
  color: var(--choice-text); font: 14px/1.4 'Instrument Sans',sans-serif; text-align: left;
  box-shadow: 0 2px 5px #00000010; color-scheme: dark;
}
.sl-component *, .sl-component *::before, .sl-component *::after { box-sizing: border-box; }
.sl-component h2 { margin: 0; font-size: 16px; line-height: 1.3; font-weight: 600; letter-spacing: -.02em; }
.sl-component .choice-intro { margin: 6px 0 12px; color: var(--choice-muted); font-size: 12px; }
.sl-component .choice-list { max-height: 280px; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--choice-border) transparent; padding: 3px; margin: -3px; }
.sl-component .choice { position: relative; display: flex; align-items: center; gap: 10px; min-height: 42px; padding: 8px; border-radius: 8px; cursor: pointer; transition: background-color 180ms ease; }
.sl-component .choice:hover { background: var(--choice-surface); }
.sl-component .choice input { position: absolute; left: 8px; width: 22px; height: 22px; margin: 0; opacity: 0; }
.sl-component .choice-mark { pointer-events: none; display: grid; place-items: center; width: 22px; height: 22px; flex: none; background: var(--choice-bg); border: 1px solid var(--choice-control); border-radius: 6px; transition: background-color 200ms ease, border-color 200ms ease, transform 180ms var(--choice-ease); }
.sl-component .choice-mark svg { width: 20px; height: 20px; stroke: var(--choice-accent-ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.sl-component .choice-tick, .sl-component .choice-dash, .sl-component .choice-dot { opacity: 0; transform-origin: center; transform: scale(.8); transition: opacity 160ms ease, transform 200ms var(--choice-ease); }
.sl-component input:checked + .choice-mark, .sl-component input[type=checkbox]:indeterminate + .choice-mark { background: var(--choice-accent); border-color: var(--choice-accent); }
.sl-component input:checked + .choice-mark .choice-tick, .sl-component input[type=checkbox]:indeterminate + .choice-mark .choice-dash { opacity: 1; transform: scale(1); }
.sl-component input[type=checkbox]:indeterminate + .choice-mark .choice-tick { opacity: 0; }
.sl-component input[type=radio] + .choice-mark { border-radius: 50%; }
.sl-component input[type=radio] + .choice-mark .choice-tick { display: none; }
.sl-component input[type=radio]:checked + .choice-mark .choice-dot { opacity: 1; transform: scale(1); fill: var(--choice-accent-ink); stroke: none; }
.sl-component input:focus-visible + .choice-mark { outline: 2px solid var(--choice-focus); outline-offset: 2px; }
.sl-component .choice:active .choice-mark { transform: scale(.94); }
.sl-component .choice:has(input:disabled) { cursor: default; color: var(--choice-muted); }
