.sl-component .sl-tolerance{position:relative;height:40px;margin:16px 6px 0;background:linear-gradient(var(--sl-track),var(--sl-track)) center/100% 2px no-repeat}.sl-component .sl-tolerance i{position:absolute;left:48%;width:4%;top:4px;bottom:4px;background:color-mix(in srgb,var(--sl-accent) 20%,transparent);border-inline:1px solid var(--sl-accent)}.sl-component .sl-tolerance b{position:absolute;left:50%;top:4px;bottom:4px;width:1px;background:var(--sl-muted)}.sl-component .sl-tolerance>span{position:absolute;left:51.4%;top:16px;width:12px;height:12px;background:var(--sl-text);transform:translateX(-50%) rotate(45deg);border:2px solid var(--sl-ink)}.sl-component .sl-tolerance-status{display:flex;align-items:center;gap:8px;margin:14px 0;font-size:12px}.sl-component .sl-tolerance-status svg{width:18px;height:18px;stroke:var(--sl-accent);stroke-width:1.6}

