@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}
.sl-component{--sl-ink:#222222;--sl-surface:#323232;--sl-edge:#464646;--sl-text:#f6f6f6;--sl-muted:#bdbdbd;--sl-accent:#e0e0e0;--sl-secondary:#959595;--sl-track:#656565;--sl-focus:#e0e0e0;--sl-ease:cubic-bezier(.2,0,0,1);box-sizing:border-box;width:320px;max-width:100%;min-width:0;margin:0;padding:16px;border:1px solid var(--sl-edge);border-radius:14px;background:var(--sl-ink);color:var(--sl-text);font:13px/1.4 'Instrument Sans',sans-serif;font-synthesis:none;text-align:left;box-shadow:0 2px 5px #00000010;container-type:inline-size}
.sl-component *,.sl-component *::before,.sl-component *::after{box-sizing:border-box}
.sl-component svg{fill:none;stroke-linecap:round;stroke-linejoin:round}
.sl-component .sl-heading{display:flex;align-items:center;gap:9px;margin:0;font-size:14px;font-weight:550;letter-spacing:-.015em}
.sl-component .sl-heading svg{width:21px;height:21px;flex:none;stroke:var(--sl-accent);stroke-width:1.5}
.sl-component .sl-context{margin:5px 0 10px;color:var(--sl-muted);font-size:10px}
.sl-component .sl-field{display:block;min-width:0;margin-top:10px}
.sl-component .sl-label{display:flex;align-items:baseline;justify-content:space-between;gap:8px;line-height:1.4;font-size:11px}
.sl-component .sl-value{white-space:nowrap;color:var(--sl-accent);font-size:12px;font-variant-numeric:tabular-nums}
.sl-component .sl-track{position:relative;display:block;height:34px;margin:0 0 0}
.sl-component .sl-track::before{content:'';position:absolute;inset:calc(50% - 2px) 10px auto;height:4px;border-radius:2px;background:linear-gradient(to right,var(--sl-accent) var(--fill),var(--sl-track) var(--fill));pointer-events:none}
.sl-component input[type="range"]{position:absolute;inset:0;appearance:none;-webkit-appearance:none;width:100%;height:100%;margin:0;border:0;background:transparent;cursor:pointer;touch-action:pan-y;color:var(--sl-text);direction:ltr}
.sl-component input[type="range"]::-webkit-slider-runnable-track{height:4px;background:transparent}
.sl-component input[type="range"]::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:20px;height:20px;margin-top:-8px;border:1px solid var(--sl-text);border-radius:6px;background:var(--sl-accent);box-shadow:0 1px 3px #0004;transition:border-radius 160ms var(--sl-ease)}
.sl-component input[type="range"]::-moz-range-track{height:4px;background:transparent}
.sl-component input[type="range"]::-moz-range-thumb{width:18px;height:18px;border:1px solid var(--sl-text);border-radius:6px;background:var(--sl-accent);box-shadow:0 1px 3px #0004}
.sl-component input[type="range"]:active::-webkit-slider-thumb{border-radius:4px}
.sl-component input:focus-visible,.sl-component button:focus-visible{outline:1px solid var(--sl-focus);outline-offset:3px;border-radius:6px}
.sl-component input:disabled,.sl-component button:disabled{cursor:default;opacity:.5}
.sl-component[data-disabled="true"] .sl-track::before{opacity:.5}
.sl-component .sl-scale{display:flex;justify-content:space-between;gap:5px;font-size:9px;color:var(--sl-muted);margin:6px 0 14px}
.sl-component .sl-summary{font-size:11px;line-height:1.5;color:var(--sl-accent);font-variant-numeric:tabular-nums;margin:10px 0 4px;overflow-wrap:anywhere}
.sl-component .sl-hint{font-size:10px;color:var(--sl-muted);margin:0;line-height:1.5}
.sl-component .sl-actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.sl-component button{font:inherit;font-size:10px;line-height:1.3;color:var(--sl-accent);background:var(--sl-surface);border:1px solid var(--sl-edge);border-radius:7px;min-height:30px;padding:6px 9px;cursor:pointer;touch-action:manipulation;transition:background 160ms var(--sl-ease),transform 160ms var(--sl-ease)}
.sl-component button:hover:enabled:not([aria-pressed="true"]){background:var(--sl-edge)}
.sl-component button:active:enabled{transform:translateY(1px)}
.sl-component button[aria-pressed="true"]{background:var(--sl-accent);color:var(--sl-ink);border-color:var(--sl-accent)}
@media(prefers-reduced-motion:reduce){.sl-component *,.sl-component *::before,.sl-component *::after{transition:none!important;animation:none!important}.sl-component input[type="range"]::-webkit-slider-thumb{transition:none}.sl-component button:active:enabled{transform:none}}
@media(forced-colors:active){.sl-component{border-color:CanvasText}.sl-component .sl-track::before{background:CanvasText}.sl-component input[type="range"]{forced-color-adjust:none}.sl-component input[type="range"]::-webkit-slider-thumb{background:Highlight;border-color:Canvas}.sl-component input[type="range"]::-moz-range-thumb{background:Highlight;border-color:Canvas}.sl-component button[aria-pressed="true"]{border:2px solid Highlight}.sl-component input:focus-visible,.sl-component button:focus-visible{outline-color:Highlight}}


.sl-component .sl-product{display:flex;align-items:center;gap:16px;margin:20px 0}.sl-component .sl-product svg{flex:none;width:56px;height:66px;stroke:var(--sl-accent);stroke-width:1.5;fill:var(--sl-surface)}.sl-component .sl-product strong,.sl-component .sl-product span{display:block}.sl-component .sl-product span{margin-top:5px;font-size:11px;color:var(--sl-muted)}.sl-component .sl-total{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:8px;border-block:1px solid var(--sl-edge);padding:14px 0}.sl-component .sl-total strong{font-size:26px;font-weight:500;font-variant-numeric:tabular-nums}.sl-component .sl-actions button{min-width:40px;font-size:18px}

