    function render() { const query=state.query.trim(), visible=state.draftTags.filter(tag=>tag.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
      q('[data-tags]').replaceChildren(...visible.map(tag=>option('tag:'+tag,tag,null,state.draft.includes(tag))));
