 data-token disabled><span><strong>Account ID</strong><small>Unavailable in this sample</small></span><span class="sl-mark" aria-hidden="true">✓</span></button></section><p data-empty class="sl-empty" hidden>No matching variables.</p></div>\n    </div>\n    <div class="sl-summary" role="region" aria-label="Local result" tabindex="0"><label><span class="sl-editor-label">Message template</span><textarea data-editor aria-label="Message template" spellcheck="false">Hello ,\nYour review is ready.</textarea></label><div class="sl-footer"><button type="button" class="sl-action" data-key="undo" disabled>Undo insertion</button></div></div>\n    <p class="sl-feedback" data-feedback role="status" aria-live="polite">Place the caret in the message, then insert.</p>\n  </div>';const Z=`@font-face { font-family: 'Instrument Sans'; src: url('./instrument-sans-variable.woff2') format('woff2'); font-weight: 400 700; font-display: swap; }
.sl-component {
  --sl-surface: #222222; --sl-panel: #2b2b2b; --sl-text: #f1f1f1; --sl-muted: #bdbdbd;
