@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}
.sl-component{--nav-surface:#232323;--nav-raised:#303030;--nav-text:#f2f2f2;--nav-muted:#bdbdbd;--nav-accent:#e0e0e0;--nav-accent-ink:#333333;--nav-border:#4e4e4e;--nav-focus:#e0e0e0;--nav-ease:cubic-bezier(.22,.61,.36,1);position:relative;width:min(320px,100%);min-width:0;box-sizing:border-box;padding:16px;border:1px solid var(--nav-border);border-radius:17px;background:var(--nav-surface);color:var(--nav-text);font:13px/1.45 'Instrument Sans',sans-serif;color-scheme:var(--nav-color-scheme,dark);box-shadow:0 3px 8px #00000014}
.sl-component *{box-sizing:border-box}
.sl-component [hidden]{display:none!important}
.sl-component :is(button,input,select){font:inherit}
.sl-component button{color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}
.sl-component :is(button,input,select,[tabindex]):focus-visible{outline:2px solid var(--nav-focus);outline-offset:2px}
.sl-component button:disabled{color:var(--nav-muted);opacity:.45;cursor:default}
.sl-component svg{width:20px;height:20px;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
