.sl-component .nv-button{min-height:36px;min-width:32px;display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid transparent;border-radius:8px;padding:7px 9px;background:transparent;text-align:left;line-height:1.25;transition:background-color 180ms var(--nav-ease),color 180ms var(--nav-ease),border-color 180ms var(--nav-ease)}
