.sl-component .nv-outline{border-color:var(--nav-border)}
.sl-component .nv-primary{background:var(--nav-accent);color:var(--nav-accent-ink)}
.sl-component .nv-primary:hover:not(:disabled){background:var(--nav-accent);border-color:var(--nav-accent)}
.sl-component .nv-row{display:flex;align-items:center;gap:6px}
.sl-component .nv-row>.nv-grow{flex:1;min-width:0}
.sl-component .nv-between{justify-content:space-between}
