.sl-component .nv-disclosure{position:absolute;z-index:2;left:16px;right:16px}.sl-component .nv-disclosure>div>.nv-list{background:var(--nav-raised);border:1px solid var(--nav-border);border-radius:10px;padding:7px;box-shadow:0 5px 10px #00000018}
