  <div class="ov-launch" data-launch><p class="ov-context">Element preview</p><button class="ov-trigger" type="button" data-trigger aria-haspopup="dialog" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 8V4h4m8 0h4v4M4 16v4h4m8 0h4v-4"/><rect x="8" y="8" width="8" height="8" rx="2"/></svg><span>Inspect appearance</span></button><p class="ov-summary" data-summary role="status">12 px corners · 100% opacity</p><p class="ov-hint">Interactive local example</p></div>
