import{retainFont as J}from"./react-font.mjs";const F="overlays-filter-builder-v11";const K='<div class="sl-component" data-kind="overlays-filter-builder-v11" data-open="false">\n  <div class="ov-launch" data-launch><p class="ov-context">Project list</p><button class="ov-trigger" type="button" data-trigger aria-haspopup="dialog" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 5h16l-6 7v6l-4 2v-8L4 5Z"/></svg><span>Filter projects</span></button><p class="ov-summary" data-summary role="status">4 projects · no filters</p><p class="ov-hint">Interactive local example</p></div>\n  <div class="ov-layer" data-layer aria-hidden="true" inert><div class="ov-backdrop" data-backdrop aria-hidden="true"></div><section class="ov-panel" data-panel tabindex="-1" role="dialog" aria-label="Project filter overlay"><header class="ov-head"><div><p class="ov-kicker">Filter</p><h2>Narrow the list</h2></div><button class="ov-close" type="button" data-close aria-label="Close project filter overlay"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m7 7 10 10M17 7 7 17"/></svg></button></header><div class="ov-body"><div class="ov-stack"><label class="ov-field"><span>Project title</span><input type="search" name="query" placeholder="Search project names" autocomplete="off"></label><label class="ov-field"><span>Status</span><span class="sl-choice"><select hidden name="status"><option value="all">Any status</option><option value="active">Active</option><option value="planned">Planned</option></select><button class="sl-choice-trigger" type="button" aria-haspopup="listbox" aria-expanded="false" aria-label="Status"><span class="sl-choice-value">Any status</span><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m7 10 5 5 5-5"/></svg></button><span class="sl-choice-list" role="listbox" aria-label="Status" aria-hidden="true" inert><button class="sl-choice-option" type="button" role="option" data-choice="all" aria-selected="false" tabindex="-1">Any status</button><button class="sl-choice-option" type="button" role="option" data-choice="active" aria-selected="false" tabindex="-1">Active</button><button class="sl-choice-option" type="button" role="option" data-choice="planned" aria-selected="false" tabindex="-1">Planned</button></span></span></label><label class="ov-check"><input type="checkbox" name="mine"><span>Only projects I own</span></label><div class="ov-note"><strong data-match-count>4 matching projects</strong><ul class="ov-list" data-matches><li>Studio website</li><li>Field notes</li><li>Mobile kit</li><li>Archive index</li></ul></div></div></div><footer class="ov-foot"><button type="button" data-action="clear">Clear filters</button><button type="button" data-action="apply" class="ov-primary">Show 4</button></footer></section></div>\n</div>';const V=`@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}
.sl-component{--ov-surface:#242424;--ov-field:#1c1c1c;--ov-text:#f0f0f0;--ov-muted:#bdbdbd;--ov-accent:#dedede;--ov-on-accent:#272727;--ov-border:#555555;--ov-focus:#d0d0d0;--ov-ink:#4b4b4b;--ov-backdrop:#0000000d;position:relative;isolation:isolate;width:min(320px,100%);height:440px;min-width:0;color:var(--ov-text);font:13px/1.45 'Instrument Sans',sans-serif;color-scheme:dark;container-type:inline-size}
.sl-component,.sl-component *{box-sizing:border-box}
.sl-component [hidden]{display:none!important}
.sl-component button,.sl-component input,.sl-component select{font:inherit;color:inherit;min-width:0}
