tage" class="fb-primary" >Stage file</button><button type="button" data-action="release" class="" >Clear 20 MB cache</button><button type="button" data-action="remove" class="" >Remove staged</button></div><p class="fb-status" data-status role="status" aria-live="polite" aria-atomic="true">Ready for local review.</p></section><div class="fb-demo"><p data-caption>Local demo · no server requests.</p></div></div>';const V=`@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}
.sl-component{--fb-surface:#222222;--fb-raised:#2d2d2d;--fb-border:#4e4e4e;--fb-text:#f6f6f6;--fb-muted:#bdbdbd;--fb-accent:#e0e0e0;--fb-on-accent:#282828;--fb-danger:#efb8a6;--fb-warning:#e8d4a5;--fb-focus:#e0e0e0;--fb-outside:#5e5e5e;width:min(320px,100%);max-width:100%;min-width:0;font:13px/1.45 'Instrument Sans',sans-serif;color:var(--fb-text);position:relative;isolation:isolate;font-synthesis:none}
