.sl-component{--dd-surface:#222222;--dd-hover:#3b3b3b;--dd-edge:#4e4e4e;--dd-text:#f6f6f6;--dd-muted:#bdbdbd;--dd-accent:#e0e0e0;--dd-selected:#353535;--dd-chart:#929292;--dd-secondary:#aec6d2;--dd-tertiary:#d3c4a8;--dd-focus:#e0e0e0;width:320px;max-width:100%;min-width:0;padding:18px;border:1px solid #ffffff12;border-radius:16px;background:var(--dd-surface);color:var(--dd-text);font:12px/1.45 'Instrument Sans',sans-serif;font-synthesis:none;-webkit-font-smoothing:antialiased;box-shadow:inset 0 1px #ffffff09,0 3px 7px #00000010;position:relative;isolation:isolate}
.sl-component,.sl-component *,.sl-component *::before,.sl-component *::after{box-sizing:border-box}.sl-component button{font:inherit;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}.sl-component button:focus-visible{outline:1.5px solid var(--dd-focus);outline-offset:-1px}.sl-component button:disabled{cursor:default;opacity:.6}.sl-component button:hover:not(:disabled){filter:brightness(1.08)}.sl-component button:active:not(:disabled){transform:translateY(1px)}.sl-component [hidden]{display:none!important}.sl-component h2,.sl-component p{margin:0}.sl-component .dd-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.sl-component h2{font-size:14px;font-weight:550;letter-spacing:-.02em;line-height:1.3}.sl-component .dd-head>svg{width:19px;height:19px;flex:none;color:var(--dd-accent)}.sl-component svg{fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.sl-component .dd-subtitle{margin-top:7px;color:var(--dd-muted);font-size:10px;line-height:1.5}.sl-component .dd-modes{display:flex;width:100%;padding:3px;gap:3px;background:#1b1b1b;border:1px solid var(--dd-edge);border-radius:8px;margin-top:17px}.sl-component .dd-modes button{flex:1;padding:6px 3px;min-height:30px;font-size:10px;line-height:1.3;min-width:0;border:0;border-radius:5px;background:none;color:var(--dd-muted);transition:background 180ms ease,color 180ms ease}.sl-component .dd-modes [aria-pressed="true"]{background:var(--dd-hover);color:var(--dd-text)}.sl-component .dd-axis{align-self:center;text-align:center;font-size:9px;color:var(--dd-muted)}.sl-component .dd-scale{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:9px;color:var(--dd-muted)}.sl-component .dd-summary{font-size:11px;color:var(--dd-accent);min-height:32px;margin-top:17px;padding-top:12px;border-top:1px solid var(--dd-edge);overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.sl-component .dd-hint{font-size:9px;color:var(--dd-muted);margin-top:8px;line-height:1.5}
.sl-component .dd-funnel{display:grid;gap:5px;margin:16px 0 6px}
.sl-component .dd-stage{background:none;padding:7px 8px;border:0;color:var(--dd-muted);border-radius:7px;transition:background 180ms ease,color 180ms ease}
.sl-component .dd-stage:hover{background:var(--dd-hover)}
.sl-component .dd-stage[aria-pressed="true"]{background:var(--dd-selected);color:var(--dd-text)}
.sl-component .dd-funnel-label{display:grid;grid-template-columns:1fr auto 36px 12px;align-items:center;gap:5px;font-size:11px;text-align:left;margin-bottom:8px}
