.sl-component .dd-funnel-label svg{width:12px;height:12px;transition:transform 180ms ease}
.sl-component .dd-stage:hover .dd-funnel-label svg{transform:translateX(2px)}
.sl-component .dd-funnel-track{display:block;height:7px;position:relative;background:var(--dd-edge);border-radius:3px;overflow:hidden}
.sl-component .dd-funnel-track i{display:block;position:absolute;inset:0;background:var(--dd-chart);border-radius:3px;transition:transform 320ms cubic-bezier(.22,.61,.36,1),background 180ms ease;transform-origin:left}
.sl-component .dd-stage[aria-pressed="true"] i{background:var(--dd-accent)}

