    function render() { paintSelection();paintModes();all('[data-select]').forEach((b,i)=>{const r=records[i],diff=r[2]-r[1],pct=Math.round(diff/r[1]*1000)/10;b.querySelector('[data-delta]').textContent=state.mode==='count'?signed(diff):signed(pct)+'%';b.setAttribute('aria-label',r[0]+', cycle 1: '+r[1]+', cycle 2: '+r[2]+' issues');});const r=records[state.selected],diff=r[2]-r[1];text('[data-summary]',r[0]+' · '+signed(diff)+' issues · '+signed(Math.round(diff/r[1]*1000)/10)+'% from cycle 1'); }
