.sl-component{--sl-surface:#222;--sl-raised:#2d2d2d;--sl-hover:#363636;--sl-inset:#191919;--sl-border:#555;--sl-grid:#6b6b6b;--sl-text:#fafafa;--sl-muted:#bdbdbd;--sl-accent:#e7e7e7;--sl-on-accent:#242424;--sl-selected:#444;--sl-focus:#f2f2f2;--sl-ease:cubic-bezier(.4,0,.2,1);box-sizing:border-box;width:min(320px,100%);min-width:0;padding:20px;border:1px solid var(--sl-border);border-radius:18px;background:var(--sl-surface);color:var(--sl-text);box-shadow:0 8px 24px #00000012;font:400 14px/1.4 'Instrument Sans',sans-serif;text-align:left;color-scheme:dark}
