.sl-control-row{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:48px}.sl-control-row>div{min-width:0}.sl-control-row strong,.sl-control-row span{display:block}.sl-control-row strong{font-size:12px;font-weight:550}.sl-control-row>div>span{margin-top:3px;color:var(--sl-muted);font-size:10px}.sl-toggle{display:flex;align-items:center;gap:7px;flex:none;min-height:40px;margin:-5px;padding:5px;border:0;border-radius:10px;background:transparent;color:var(--sl-text);cursor:pointer;touch-action:manipulation}.sl-toggle-word{width:19px;color:var(--sl-muted);font-size:10px;text-align:right}.sl-toggle-track{display:block;position:relative;width:42px;height:24px;border:1px solid var(--sl-border);border-radius:99px;background:var(--sl-inset);transition:background-color 240ms ease,border-color 240ms ease}.sl-toggle-track::after{content:"";position:absolute;left:3px;top:3px;width:16px;height:16px;border-radius:50%;background:var(--sl-muted);box-shadow:0 1px 2px #0006;transition:transform 300ms var(--sl-ease),background-color 220ms ease}.sl-toggle[aria-checked="true"] .sl-toggle-track{background:var(--sl-selected);border-color:var(--sl-muted)}.sl-toggle[aria-checked="true"] .sl-toggle-track::after{transform:translateX(18px);background:var(--sl-accent)}
.sl-segments{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:4px;padding:4px;border:1px solid var(--sl-border);border-radius:11px;background:var(--sl-inset)}.sl-segments button{min-width:0;min-height:38px;padding:7px 6px;border:0;border-radius:7px;background:transparent;color:var(--sl-muted);font-size:10px;cursor:pointer;transition:background-color 220ms ease,color 180ms ease,transform 180ms var(--sl-ease)}.sl-segments button[aria-checked="true"]{background:var(--sl-selected);color:var(--sl-text);font-weight:600}.sl-segments button:active{transform:scale(.98)}
.sl-segments button:hover{background-color:var(--sl-hover)}.sl-toggle:focus-visible,.sl-segments button:focus-visible{outline:2px solid var(--sl-focus);outline-offset:2px}.sl-preview{margin-top:16px;border:1px solid var(--sl-border);border-radius:12px;background:var(--sl-inset)}.sl-status{min-height:32px;margin:14px 0 0;padding-top:11px;border-top:1px solid var(--sl-border);color:var(--sl-muted);font-size:10px;overflow-wrap:anywhere}
.sl-component[data-destroyed="true"] *,.sl-component[data-destroyed="true"] *::before,.sl-component[data-destroyed="true"] *::after{transition:none!important;animation:none!important}@media(max-width:260px){.sl-component{padding:16px}.sl-toggle-word{display:none}.sl-control-row{gap:8px}}@media(prefers-reduced-motion:reduce){.sl-component *,.sl-component *::before,.sl-component *::after{transition:none!important;animation:none!important;scroll-behavior:auto!important}}@media(forced-colors:active){.sl-component,.sl-preview,.sl-segments,.sl-toggle-track{border-color:CanvasText}.sl-toggle:focus-visible,.sl-segments button:focus-visible{outline-color:Highlight}.sl-toggle[aria-checked="true"] .sl-toggle-track::after,.sl-segments button[aria-checked="true"]{background:Highlight;color:HighlightText}}

.sl-app{border-radius:11px;height:86px;display:flex;overflow:hidden}.sl-app aside{width:40px;flex:none;padding:9px 7px;border-right:1px solid var(--sl-border);background:var(--sl-raised);transition:width 360ms var(--sl-ease)}.sl-app aside div{height:21px;display:flex;align-items:center;gap:7px;overflow:hidden}.sl-app aside i{width:10px;height:10px;flex:none;border:1px solid var(--sl-muted);border-radius:3px}.sl-app aside span{opacity:0;white-space:nowrap;color:var(--sl-muted);font-size:9px;transform:translateX(-5px);transition:opacity 180ms ease,transform 300ms var(--sl-ease)}.sl-app main{flex:1;padding:15px 13px;display:grid;align-content:start;gap:8px}.sl-app main i{height:4px;border-radius:4px;background:var(--sl-border)}.sl-app main i:nth-child(2){width:72%}.sl-app main i:nth-child(3){width:86%}.sl-component[data-state="labels"] .sl-app aside{width:92px}.sl-component[data-state="labels"] .sl-app aside span{opacity:1;transform:translateX(0)}

