import{retainFont as J}from"./react-font.mjs";const $="buttons-everyday-buttons-invite-v11";const K='<section class="sl-component" data-kind="buttons-everyday-buttons-invite-v11" aria-label="Invite member"><p role="status">Initializing invite member…</p></section>';const X="@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}.sl-component{width:100%;max-width:320px;min-width:0;color:#222;font:14px/1.45 'Instrument Sans',sans-serif;font-synthesis:none;-webkit-font-smoothing:antialiased;}.everyday-component{--action-surface:#303030;--action-hover:#3b3b3b;--action-text:#f6f6f6;--action-muted:#696969;--action-edge:#d3d3d3;--action-focus:#4b4b4b;--action-feedback:#505050;--action-ease:cubic-bezier(.22,1,.36,1);width:320px;max-width:100%;min-width:0;display:flex;flex-direction:column;align-items:center;gap:20px}
