import{retainFont as Q}from"./react-font.mjs";const B="selection-daily-controls-payment-v11";const J='<section class="sl-component" data-kind="selection-daily-controls-payment-v11" aria-label="Checkout payment choice"><p role="status">Initializing checkout payment choice…</p></section>';const K=`@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}.sl-component{width:100%;max-width:320px;min-width:0;}.daily-control{--dc-surface:#303030;--dc-layer:#222;--dc-action:#252525;--dc-text:#f4f4f4;--dc-muted:#c6c6c6;--dc-edge:#505050;--dc-focus:#eee;--dc-hover:#393939;--dc-selected:#4b4b4b;--dc-fast:200ms;--dc-duration:300ms;--dc-ease:cubic-bezier(.22,1,.36,1);width:100%;max-width:320px;min-width:0;margin-inline:auto;padding:20px;box-sizing:border-box;background:var(--dc-surface);color:var(--dc-text);border:1px solid var(--dc-edge);border-radius:20px;box-shadow:0 6px 18px #0000000b,0 1px 2px #00000010;font:400 16px/1.45 'Segoe UI',sans-serif;font-synthesis:none}
.daily-control *,.daily-control *::before,.daily-control *::after{box-sizing:border-box}
.daily-control .dc-title{margin:0 0 6px;font-size:19px;line-height:1.3;font-weight:600;letter-spacing:-.25px}
.daily-control .dc-hint{display:block;margin:0;color:var(--dc-muted);font-size:13px;font-weight:400;line-height:1.55;letter-spacing:0}
.daily-control>.dc-hint{margin-bottom:22px}
