.daily-control .dc-brand svg{height:40px;width:40px;stroke-width:1.5;transition:transform var(--dc-duration) var(--dc-ease)}
.daily-control .dc-brand[data-active=true]{color:#fff;background:#ffffff07}.daily-control .dc-brand[data-active=true] svg{transform:translateY(-4px)}
.daily-control .dc-brand-name{font-size:13px;line-height:1.4;font-weight:500}
.daily-control .dc-brand-detail{min-height:65px;padding-top:14px;border-top:1px solid var(--dc-edge)}
.daily-control .dc-brand-detail .dc-hint{margin-top:4px}
.daily-control .dc-brand-descriptions .dc-state{transform:none;transition:opacity var(--dc-fast) var(--dc-ease),visibility 0s var(--dc-fast)}
.daily-control .dc-brand-descriptions .dc-state[data-active=true]{transition:opacity var(--dc-fast) var(--dc-ease),visibility 0s}
.daily-control .dc-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px;margin-bottom:20px}
.daily-control .dc-week .dc-button{padding:8px 0;min-height:40px;border-radius:9px;font-size:14px;background:transparent;box-shadow:none;border-color:transparent}
.daily-control .dc-week .dc-button[aria-pressed=true]{background:var(--dc-selected);border-color:#7b7b7b;color:white}
.daily-control .dc-hours{display:flex;gap:12px;padding:20px 14px;border:1px solid var(--dc-edge);background:var(--dc-layer);border-radius:14px;min-height:135px}
.daily-control .dc-hours>svg{margin-top:3px;color:var(--dc-muted)}.daily-control .dc-hours>div{min-width:0}
.daily-control .dc-time-value{display:block;font-size:24px;font-weight:500;line-height:1.3;margin:9px 0 4px;font-variant-numeric:tabular-nums;letter-spacing:-.3px}
.daily-control .dc-workspace{--split:50%;display:grid;grid-template-columns:minmax(0,calc(var(--split) - 9px)) 18px minmax(0,1fr);height:194px;margin-bottom:10px;border:1px solid var(--dc-edge);border-radius:13px;background:var(--dc-layer);overflow:hidden}
.daily-control .dc-pane{min-width:0;padding:13px 8px;overflow:hidden}
.daily-control .dc-pane-label{display:block;white-space:nowrap;color:var(--dc-muted);font-size:12px;margin-bottom:17px}
.daily-control .dc-document{display:block;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:8px 0;border-bottom:1px solid #ffffff0d}
.daily-control .dc-separator{position:relative;display:grid;place-items:center;cursor:col-resize;touch-action:none;background:#ffffff03}
.daily-control .dc-separator::before{content:'';position:absolute;inset:0 8px;background:#595959;transition:background var(--dc-fast) var(--dc-ease)}
.daily-control .dc-separator>span{width:4px;height:28px;border-radius:4px;background:#a8a8a8;z-index:1;transition:height var(--dc-fast) var(--dc-ease),background var(--dc-fast) var(--dc-ease)}
.daily-control .dc-separator:hover>span,.daily-control .dc-workspace[data-dragging=true] .dc-separator>span{height:38px;background:#fff}
.daily-control .dc-separator:focus-visible{outline:0}
.daily-control .dc-separator:focus-visible>span{outline:2px solid var(--dc-focus);outline-offset:5px}
.daily-control .dc-workspace{user-select:none}
.daily-control .dc-mini-page{height:118px;background:linear-gradient(155deg,#515151,#383838);border:1px solid #646464;border-radius:6px;padding:10px}
.daily-control .dc-mini-page::before,.daily-control .dc-mini-page::after{content:'';display:block;height:4px;background:#929292;border-radius:2px;margin:8px 0;width:75%}.daily-control .dc-mini-page::after{width:50%;opacity:.6}
.daily-control .dc-tracking{position:relative;margin:20px 0;padding-left:33px}
.daily-control .dc-tracking>svg{position:absolute;left:0;top:1px;color:var(--dc-muted)}
.daily-control .dc-tracking .dc-label{font-size:13px;font-weight:400;color:var(--dc-muted)}
.daily-control .dc-arrival{display:block;font-weight:500;font-size:18px;line-height:1.4;margin-top:5px}
.daily-control .dc-track-list{padding:0;margin:0;list-style:none;display:grid;gap:0}
.daily-control .dc-track-list li{position:relative;display:flex;align-items:center;gap:13px;min-height:37px;color:#acacac;font-size:15px;transition:color var(--dc-duration) var(--dc-ease)}
.daily-control .dc-track-list li:not(:last-child)::before{content:'';position:absolute;left:7px;width:1px;top:24px;bottom:-13px;background:#5e5e5e}
.daily-control .dc-track-dot{display:grid;place-items:center;width:15px;height:15px;border:1px solid #888;border-radius:50%;flex-shrink:0;background:var(--dc-surface);transition:background var(--dc-duration) var(--dc-ease),border-color var(--dc-duration) var(--dc-ease)}
.daily-control .dc-track-list [data-complete=true]{color:var(--dc-text)}.daily-control [data-complete=true] .dc-track-dot{background:#d6d6d6;border-color:#d6d6d6}
