@font-face{font-family:'Instrument Sans';src:url('./instrument-sans-variable.woff2') format('woff2');font-weight:400 700;font-display:swap}.sl-component{width:100%;max-width:320px;min-width:0}.account-control{--ac-surface:#303030;--ac-layer:#252525;--ac-text:#f4f4f4;--ac-muted:#c6c6c6;--ac-edge:#505050;--ac-fast:200ms;--ac-duration:300ms;--ac-ease:cubic-bezier(.22,1,.36,1);box-sizing:border-box;width:100%;max-width:320px;min-width:0;padding:20px;background:var(--ac-surface);color:var(--ac-text);border:1px solid var(--ac-edge);border-radius:20px;box-shadow:0 6px 18px #0000000b,0 1px 2px #00000010;font:400 16px/1.45 'Segoe UI',sans-serif;font-synthesis:none}
